const ROOT_NAME='Construction Dashboard'; const PROJECT='Lincoln';
const ASSETS={"photos": {"p1": "", "p2": "", "p3": "", "p4": "", "p5": "", "p6": ""}, "pdf": ""};
let _svc={token:null,exp:0};
async function serviceToken(){ if(_svc.token&&Date.now()<_svc.exp-60000) return _svc.token; const body=new URLSearchParams({grant_type:'client_credentials',client_id:process.env.BOX_SVC_CLIENT_ID,client_secret:process.env.BOX_SVC_CLIENT_SECRET,box_subject_type:'enterprise',box_subject_id:process.env.BOX_ENTERPRISE_ID}); const r=await fetch('https://api.box.com/oauth2/token',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body}); const d=await r.json(); if(!d.access_token) return null; _svc={token:d.access_token,exp:Date.now()+(d.expires_in||3600)*1000}; return _svc.token; }
const H=t=>({Authorization:'Bearer '+t});
async function list(t,id){ const r=await fetch(`https://api.box.com/2.0/folders/${id}/items?limit=1000&fields=id,name,type`,{headers:H(t)}); return r.ok?(await r.json()).entries||[]:[]; }
const csvEsc=v=>{const s=String(v==null?'':v);return /[",\n]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s;};
function parseCSV(text){ if(!text||!text.trim()) return {headers:[],rows:[]}; const lines=text.replace(/\r/g,'').split('\n').filter(l=>l.length); const pl=line=>{const res=[];let cur='',q=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'){if(q&&line[i+1]==='"'){cur+='"';i++;}else q=!q;}else if(c===','&&!q){res.push(cur.trim());cur='';}else cur+=c;}res.push(cur.trim());return res;}; const headers=pl(lines[0]); const rows=lines.slice(1).map(l=>{const v=pl(l),o={};headers.forEach((h,i)=>o[h]=v[i]!==undefined?v[i]:'');return o;}); return {headers,rows}; }
function toCSV(headers,rows){ return headers.join(',')+'\n'+rows.map(r=>headers.map(h=>csvEsc(r[h])).join(',')).join('\n')+'\n'; }
function b64ToBlob(b64,mime){ const bin=atob(b64); const arr=new Uint8Array(bin.length); for(let i=0;i<bin.length;i++) arr[i]=bin.charCodeAt(i); return new Blob([arr],{type:mime}); }
async function findCSV(t,folderId){ return (await list(t,folderId)).find(i=>i.type==='file'&&i.name.toLowerCase().endsWith('.csv')); }
async function ensureFolder(t,parent,name){ const items=await list(t,parent); const f=items.find(i=>i.type==='folder'&&i.name===name); if(f) return f.id; const r=await fetch('https://api.box.com/2.0/folders',{method:'POST',headers:{...H(t),'Content-Type':'application/json'},body:JSON.stringify({name,parent:{id:String(parent)}})}); if(r.ok) return (await r.json()).id; if(r.status===409){ const it=await list(t,parent); const f2=it.find(i=>i.type==='folder'&&i.name===name); if(f2) return f2.id; } return null; }
async function uploadFile(t,folder,name,b64,mime){ const items=await list(t,folder); const ex=items.find(i=>i.type==='file'&&i.name===name); if(ex) return ex.id; const form=new FormData(); form.append('attributes',JSON.stringify({name,parent:{id:String(folder)}})); form.append('file',b64ToBlob(b64,mime),name); const r=await fetch('https://upload.box.com/api/2.0/files/content',{method:'POST',headers:H(t),body:form}); if(!r.ok) return ''; const d=await r.json(); return (d.entries?d.entries[0]:d).id||''; }
async function writeCSV(t,folderId,name,headers,rows){ const ex=await findCSV(t,folderId); const out=toCSV(headers,rows); const form=new FormData(); form.append('attributes',JSON.stringify(ex?{name}:{name,parent:{id:String(folderId)}})); form.append('file',b64ToBlob(btoa(unescape(encodeURIComponent(out))),'text/csv'),name); const url=ex?`https://upload.box.com/api/2.0/files/${ex.id}/content`:'https://upload.box.com/api/2.0/files/content'; const r=await fetch(url,{method:'POST',headers:H(t),body:form}); return r.ok; }
async function readCSVrows(t,folderId){ const csv=await findCSV(t,folderId); if(!csv) return null; const txt=await (await fetch(`https://api.box.com/2.0/files/${csv.id}/content`,{headers:H(t)})).text(); const p=parseCSV(txt); return {csv,headers:p.headers,rows:p.rows}; }
const LABEL={rfi:'RFI',co:'CO',sub:'Submittal'};
const IDF={rfi:'RFI #',co:'CO #',sub:'Submittal #'};

async function doPhotos(t,gf){ const dailyF=gf('04'); if(!dailyF) return 'no daily'; const photosF=await ensureFolder(t,dailyF,'Photos'); const dates={'2026-07-15':['p1','p2','p3'],'2026-07-28':['p4','p5','p6']}; for(const [date,keys] of Object.entries(dates)){ const dF=await ensureFolder(t,photosF,date); let n=1; for(const k of keys) await uploadFile(t,dF,'site-photo-'+(n++)+'.jpg',ASSETS.photos[k],'image/jpeg'); } return 'photos: 2 dates x 3'; }
async function doThread(t,gf,key,pfx){ const modF=gf(pfx); if(!modF) return key+': no folder'; const data=await readCSVrows(t,modF); if(!data) return key+': no csv'; const {csv,headers,rows}=data; if(!headers.includes('Version History')) headers.push('Version History'); const idField=IDF[key]; for(const row of rows){ const num=row[idField]||'item'; const itemF=await ensureFolder(t,modF,LABEL[key]+' #'+num); let vh=[]; try{vh=JSON.parse(row['Version History']||'[]');}catch(e){} if(vh.length){ for(const v of vh){ const fn=v.fileName||(num+' v'+v.v+'.pdf'); v.fileId=await uploadFile(t,itemF,fn,ASSETS.pdf,'application/pdf'); v.fileName=fn; } const last=vh[vh.length-1]; row['Attachment File ID']=last.fileId; row['Attachment Name']=last.fileName; } else { const fn=num+' - document.pdf'; const fid=await uploadFile(t,itemF,fn,ASSETS.pdf,'application/pdf'); row['Attachment File ID']=fid; row['Attachment Name']=fn; vh=[{v:1,fileId:fid,fileName:fn,status:row['Status']||'',date:row['Date Submitted']||'',by:'',note:'Submitted'}]; } row['Version History']=JSON.stringify(vh); } await writeCSV(t,modF,csv.name,headers,rows); return key+': '+rows.length+' attached'; }
async function doDocs(t,gf){ const docF=gf('07'); if(!docF) return 'no docs'; const data=await readCSVrows(t,docF); if(!data) return 'no docs csv'; const {csv,headers,rows}=data; for(const row of rows){ const name=row['Document Name']||'Document'; const itemF=await ensureFolder(t,docF,name); const fn=name+'.pdf'; const fid=await uploadFile(t,itemF,fn,ASSETS.pdf,'application/pdf'); row['File ID']=fid; row['File Name']=fn; } await writeCSV(t,docF,csv.name,headers,rows); return 'docs: '+rows.length+' attached'; }
async function doPay(t,gf){ const payF=gf('09'); if(!payF) return 'no pay'; const data=await readCSVrows(t,payF); if(!data) return 'no pay csv'; const {csv,headers,rows}=data; for(const row of rows){ const num=row['App #']||'PA'; const contr=row['Contractor']||''; const itemF=await ensureFolder(t,payF,contr+' - '+num); let vh=[]; try{vh=JSON.parse(row['Version History']||'[]');}catch(e){} for(const v of vh){ const fn=v.fileName||(num+' v'+v.v+'.pdf'); v.fileId=await uploadFile(t,itemF,fn,ASSETS.pdf,'application/pdf'); v.fileName=fn; } if(vh.length){ row['Attachment File ID']=vh[0].fileId; row['Attachment Name']=vh[0].fileName; const last=vh[vh.length-1]; const st=(row['Status']||'').toLowerCase(); if(vh.length>1&&st.includes('signed')){ row['Signed File ID']=last.fileId; row['Signed File Name']=last.fileName; } row['Version History']=JSON.stringify(vh); } } await writeCSV(t,payF,csv.name,headers,rows); return 'payapps: '+rows.length+' attached'; }

export default async (req)=>{
  const url=new URL(req.url); if(url.searchParams.get('token')!=='fidevia-files-7k4') return new Response('nope',{status:403});
  const step=url.searchParams.get('step')||'photos';
  const t=await serviceToken(); if(!t) return new Response('no token',{status:500});
  const root=(await list(t,'0')).find(i=>i.type==='folder'&&i.name===ROOT_NAME); if(!root) return new Response('no root');
  const proj=(await list(t,root.id)).find(i=>i.type==='folder'&&i.name.includes(PROJECT)); if(!proj) return new Response('no lincoln');
  const subs=await list(t,proj.id); const gf=p=>{const f=subs.find(i=>i.type==='folder'&&i.name.startsWith(p));return f?f.id:null;};
  let res;
  if(step==='photos') res=await doPhotos(t,gf);
  else if(step==='rfi') res=await doThread(t,gf,'rfi','01');
  else if(step==='co') res=await doThread(t,gf,'co','02');
  else if(step==='sub') res=await doThread(t,gf,'sub','03');
  else if(step==='docs') res=await doDocs(t,gf);
  else if(step==='pay') res=await doPay(t,gf);
  else res='unknown step';
  return new Response(JSON.stringify({ok:true,step,res}),{headers:{'Content-Type':'application/json'}});
};
